{"file_path":"src/parse.js","content":"/**
 * Splits raw standard input into the three documents (mine, base, theirs)
 * separated by lines that are exactly `%%%`.
 */

/** Thrown when the input does not hold exactly three parts. */
export class InputError extends Error {}

/**
 * Splits `raw` stdin text into lines, dropping the empty tail a trailing
 * newline leaves, then groups those lines into documents separated by `%%%`
 * lines. Throws InputError unless there are exactly three documents.
 */
export function parseInput(raw) {
  const lines = raw.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) throw new InputError('expected three parts separated by %%%')
  return parts
}
"}

