{"file_path":"src/lcs-diff.js","content":"/**
 * Computes the changes needed to turn `base` into `other`, from a longest
 * common subsequence of whole lines compared as exact strings.
 */

/**
 * Returns the changes that replace runs of `base` lines with runs of
 * `other` lines, ordered by where they start in `base`. Ties in the LCS
 * length are broken by preferring the earliest matches: walking both
 * documents from the start, a match is taken whenever the current lines
 * are equal, and otherwise the side whose remaining subsequence is at
 * least as long as the other's is advanced, preferring to advance `base`
 * when they tie.
 */
export function computeChanges(base, other) {
  const n = base.length
  const m = other.length

  // dp[i][j] holds the LCS length of base[i:] and other[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === other[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === other[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  const changes = []
  let baseCursor = 0
  let otherCursor = 0
  for (const [mi, mj] of matches) {
    if (mi > baseCursor || mj > otherCursor) {
      changes.push({ baseStart: baseCursor, baseEnd: mi, otherStart: otherCursor, otherEnd: mj })
    }
    baseCursor = mi + 1
    otherCursor = mj + 1
  }
  if (baseCursor < n || otherCursor < m) {
    changes.push({ baseStart: baseCursor, baseEnd: n, otherStart: otherCursor, otherEnd: m })
  }
  return changes
}
"}

