{"file_path":"src/regions.js","content":"/**
 * Groups the changes from both sides into regions: stretches of the base
 * document that are either left stable or touched by one or more changes.
 */

/**
 * Merges `mineChanges` and `theirsChanges` (each as returned by
 * computeChanges, tagged with their side) into a single ordered list, then
 * walks it to build regions. A region absorbs every subsequent change that
 * starts at or before its current end, extending the end to cover it. The
 * base stretches before, between and after regions are stable regions.
 */
export function buildRegions(baseLength, mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(change => ({ ...change, side: 'mine' })),
    ...theirsChanges.map(change => ({ ...change, side: 'theirs' })),
  ]
  tagged.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let pos = 0
  let idx = 0
  while (idx < tagged.length) {
    const first = tagged[idx]
    if (first.baseStart > pos) {
      regions.push({ type: 'stable', baseStart: pos, baseEnd: first.baseStart })
    }

    let end = first.baseEnd
    const changes = [first]
    idx++
    while (idx < tagged.length && tagged[idx].baseStart <= end) {
      end = Math.max(end, tagged[idx].baseEnd)
      changes.push(tagged[idx])
      idx++
    }

    regions.push({ type: 'changed', baseStart: first.baseStart, baseEnd: end, changes })
    pos = end
  }
  if (pos < baseLength) regions.push({ type: 'stable', baseStart: pos, baseEnd: baseLength })

  return regions
}
"}

