{"file_path":"src/resolve.js","content":"/**
 * Resolves a changed region to the lines it should produce, or to a
 * conflict between mine and theirs.
 */

function arraysEqual(a, b) {
  return a.length === b.length && a.every((value, index) => value === b[index])
}

/**
 * Assembles one side's lines across `region`: the base lines the region
 * covers, with each of that side's own changes replaced by its own lines,
 * and every other base line in the region (unchanged by that side) kept as
 * is. This is equivalent to running the side's replacement from the
 * smallest start of its own changes, moved back to the region's start, to
 * the largest end of its own changes, moved forward to the region's end.
 */
function assembleSide(baseLines, sideLines, region, side) {
  const sideChanges = region.changes.filter(change => change.side === side).sort((a, b) => a.baseStart - b.baseStart)

  const result = []
  let pos = region.baseStart
  for (const change of sideChanges) {
    result.push(...baseLines.slice(pos, change.baseStart))
    result.push(...sideLines.slice(change.otherStart, change.otherEnd))
    pos = change.baseEnd
  }
  result.push(...baseLines.slice(pos, region.baseEnd))
  return result
}

/**
 * Resolves a changed region given the full base, mine and theirs
 * documents. Returns `{ kind: 'both' | 'mine' | 'theirs', lines }` when the
 * region resolves cleanly, or `{ kind: 'conflict', mineLines, baseLines,
 * theirsLines }` when it doesn't.
 */
export function resolveRegion(baseDoc, mineDoc, theirsDoc, region) {
  const mineLines = assembleSide(baseDoc, mineDoc, region, 'mine')
  const theirsLines = assembleSide(baseDoc, theirsDoc, region, 'theirs')
  const baseLines = baseDoc.slice(region.baseStart, region.baseEnd)

  if (arraysEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
