{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input
 * (mine, base and theirs, separated by `%%%` lines) and report the
 * three-way merge of the base into mine and theirs.
 */

import { readFileSync } from 'node:fs'
import { parseInput, InputError } from './parse.js'
import { computeChanges } from './lcs-diff.js'
import { buildRegions } from './regions.js'
import { resolveRegion } from './resolve.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (!MODES.has(mode)) fail('usage: cli.js merge|merge2|regions')

  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseInput(readFileSync(0, 'utf8'))
  } catch (error) {
    if (error instanceof InputError) fail(error.message)
    throw error
  }

  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegions(base.length, mineChanges, theirsChanges)

  const output = []
  let conflict = false

  for (const region of regions) {
    if (region.type === 'stable') {
      const lines = base.slice(region.baseStart, region.baseEnd)
      if (mode === 'regions') output.push(`stable ${lines.length}`)
      else output.push(...lines)
      continue
    }

    const resolved = resolveRegion(base, mine, theirs, region)

    if (resolved.kind !== 'conflict') {
      if (mode === 'regions') output.push(`${resolved.kind} ${resolved.lines.length}`)
      else output.push(...resolved.lines)
      continue
    }

    conflict = true
    if (mode === 'regions') {
      output.push(
        `conflict mine=${resolved.mineLines.length} base=${resolved.baseLines.length} theirs=${resolved.theirsLines.length}`,
      )
      continue
    }

    output.push('<<<<<<< mine')
    output.push(...resolved.mineLines)
    if (mode === 'merge') {
      output.push('||||||| base')
      output.push(...resolved.baseLines)
    }
    output.push('=======')
    output.push(...resolved.theirsLines)
    output.push('>>>>>>> theirs')
  }

  process.stdout.write(output.length > 0 ? `${output.join('\n')}\n` : '')
  process.exit(conflict ? 1 : 0)
}

main()
"}

